1	package wallet
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"sync"
8		"time"
9	)
10	
11	// Wallet 是进程内的智能钱包。
12	//
13	// 所有方法都可被多个 goroutine 并发调用；每一次申请、结算或取消都在
14	// 同一把锁内原子完成，因此余额与共享累计额度不会被超扣，同一请求也
15	// 只会产生一个终态。状态仅在当前 Wallet 实例的生命周期内保留。
16	type Wallet struct {
17		mu sync.Mutex
18	
19		// now 可在同包测试中替换，默认使用 time.Now。
20		now func() time.Time
21	
22		accounts map[string]*account
23		sessions map[string]*session
24		policies map[string]*policy
25		// requests 以“使用账户编号 + 请求编号”为键，实现按使用账户的幂等。
26		requests map[requestKey]*request
27		ledger   []LedgerEntry
28	}
29	
30	type account struct {
31		id        string
32		available int64
33		reserved  int64
34		createdAt time.Time
35	}
36	
37	type session struct {
38		id        string
39		accountID string
40		deviceID  string
41		expiresAt time.Time
42		revoked   bool
43		createdAt time.Time
44	}
45	
46	type policy struct {
47		id                string
48		payerAccountID    string
49		allowedAccounts   map[string]struct{}
50		operation         string
51		payee             string
52		startsAt          time.Time
53		endsAt            time.Time
54		maxPerRequest     int64
55		maxTotal          int64
56		approvalThreshold int64
57		approvalWait      time.Duration
58		// maxReserveDuration 为最长预留时长；零表示关闭预留超时。
59		maxReserveDuration time.Duration
60		reservedTotal      int64
61		spentTotal         int64
62	
63		deactivated          bool
64		deactivatedAt        time.Time
65		deactivatorAccountID string
66		deactivateReason     string
67	}
68	
69	type request struct {
70		policyID       string
71		requestID      string
72		accountID      string
73		payerAccountID string
74		sessionID      string
75		operation      string
76		payee          string
77		estimatedFee   int64
78		actualFee      int64
79		state          RequestState
80		createdAt      time.Time
81		settledAt      time.Time
82		waitDeadline   time.Time
83		// reservedAt 为费用实际预留完成的时刻（直接受理或批准成功的时刻）。
84		reservedAt time.Time
85		// reserveDuration 为预留时适用的最长预留时长快照；零表示未启用超时。
86		reserveDuration time.Duration
87		// reserveDeadline 为预留截止时刻（reservedAt + reserveDuration）。
88		reserveDeadline time.Time
89		// reserveExpiredAt 为超时释放时间；惰性处理时记录的仍是截止时刻本身。
90		reserveExpiredAt  time.Time
91		decidedAt         time.Time
92		approverAccountID string
93		rejectReason      string
94	}
95	
96	type requestKey struct {
97		accountID string
98		requestID string
99	}
100	
101	// New 创建一个空钱包。
102	func New() *Wallet {
103		return &Wallet{
104			now:      time.Now,
105			accounts: make(map[string]*account),
106			sessions: make(map[string]*session),
107			policies: make(map[string]*policy),
108			requests: make(map[requestKey]*request),
109		}
110	}
111	
112	// CreateAccount 创建具有唯一编号和初始代付余额的账户。
113	//
114	// 金额为最小货币单位的整数；初始余额为负或编号重复时返回错误，
115	// 且不会改动任何已有资金记录。
116	func (w *Wallet) CreateAccount(id string, initialBalance int64) (AccountView, error) {
117		if id == "" {
118			return AccountView{}, ErrEmptyAccountID
119		}
120		if initialBalance < 0 {
121			return AccountView{}, fmt.Errorf("%w: initial balance must not be negative", ErrInvalidAmount)
122		}
123	
124		w.mu.Lock()
125		defer w.mu.Unlock()
126	
127		if _, ok := w.accounts[id]; ok {
128			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountExists, id)
129		}
130		now := w.now()
131		acc := &account{id: id, available: initialBalance, createdAt: now}
132		w.accounts[id] = acc
133		return acc.view(), nil
134	}
135	
136	// Account 查询账户视图；账户不存在时返回 ErrAccountNotFound。
137	// 查询时已到期的预留会先被自动释放，因此视图反映最新的可用/预留余额。
138	func (w *Wallet) Account(id string) (AccountView, error) {
139		w.mu.Lock()
140		defer w.mu.Unlock()
141	
142		acc, ok := w.accounts[id]
143		if !ok {
144			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, id)
145		}
146		w.expireReservationsLocked(w.now())
147		return acc.view(), nil
148	}
149	
150	// Balance 查询账户的可用余额与预留余额。
151	func (w *Wallet) Balance(id string) (Balances, error) {
152		view, err := w.Account(id)
153		if err != nil {
154			return Balances{}, err
155		}
156		return view.Balances, nil
157	}
158	
159	// CreateSession 为账户创建一个绑定设备、带到期时间的会话。
160	//
161	// 会话编号全局唯一；账户必须存在。
162	func (w *Wallet) CreateSession(id, accountID, deviceID string, expiresAt time.Time) (SessionView, error) {
163		if id == "" || accountID == "" || deviceID == "" {
164			return SessionView{}, fmt.Errorf("%w: session id, account id and device id are required", ErrInvalidArgument)
165		}
166	
167		w.mu.Lock()
168		defer w.mu.Unlock()
169	
170		if _, ok := w.accounts[accountID]; !ok {
171			return SessionView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, accountID)
172		}
173		if _, ok := w.sessions[id]; ok {
174			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionExists, id)
175		}
176		now := w.now()
177		sess := &session{
178			id:        id,
179			accountID: accountID,
180			deviceID:  deviceID,
181			expiresAt: expiresAt,
182			createdAt: now,
183		}
184		w.sessions[id] = sess
185		return sess.view(), nil
186	}
187	
188	// RevokeSession 主动吊销会话。会话不存在返回错误；重复吊销视为成功。
189	// 吊销后不再受理该会话的新申请；仍在待审批的请求进入拒绝终态并说明
190	// 原因，已预留费用的请求仍可结算或取消。
191	func (w *Wallet) RevokeSession(id string) error {
192		w.mu.Lock()
193		defer w.mu.Unlock()
194	
195		sess, ok := w.sessions[id]
196		if !ok {
197			return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
198		}
199		if sess.revoked {
200			return nil
201		}
202		sess.revoked = true
203		now := w.now()
204		reason := "application session revoked before approval"
205		// 仍在待审批的请求随会话吊销进入拒绝终态。
206		for _, req := range w.requests {
207			if req.state == RequestPendingApproval && req.sessionID == sess.id {
208				req.state = RequestRejected
209				req.rejectReason = reason
210				req.decidedAt = now
211				w.ledger = append(w.ledger, LedgerEntry{
212					Kind:      LedgerRejection,
213					AccountID: req.accountID,
214					RequestID: req.requestID,
215					Reason:    reason,
216					At:        now,
217				})
218			}
219		}
220		return nil
221	}
222	
223	// Session 查询会话视图。
224	func (w *Wallet) Session(id string) (SessionView, error) {
225		w.mu.Lock()
226		defer w.mu.Unlock()
227	
228		sess, ok := w.sessions[id]
229		if !ok {
230			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
231		}
232		return sess.view(), nil
233	}
234	
235	// SavePolicy 保存（创建）一条代付策略。
236	//
237	// 出资账户和所有使用账户必须存在，限额必须为正，开始时间必须严格早于
238	// 结束时间，编号不得重复，否则拒绝保存并返回包装了具体原因的错误。
239	func (w *Wallet) SavePolicy(spec PolicySpec) error {
240		if spec.ID == "" {
241			return fmt.Errorf("%w: policy id is required", ErrPolicyInvalid)
242		}
243		if spec.Operation == "" || spec.Payee == "" {
244			return fmt.Errorf("%w: operation and payee are required", ErrPolicyInvalid)
245		}
246		if spec.MaxPerRequest <= 0 || spec.MaxTotal <= 0 {
247			return fmt.Errorf("%w: limits must be positive", ErrPolicyInvalid)
248		}
249		// 审批门槛：零表示关闭；不得为负，不得超过单次上限；开启时等待时长必须为正。
250		if spec.ApprovalThreshold < 0 {
251			return fmt.Errorf("%w: approval threshold must not be negative", ErrPolicyInvalid)
252		}
253		if spec.ApprovalThreshold > 0 {
254			if spec.ApprovalThreshold > spec.MaxPerRequest {
255				return fmt.Errorf("%w: approval threshold %d exceeds per-request limit %d", ErrPolicyInvalid, spec.ApprovalThreshold, spec.MaxPerRequest)
256			}
257			if spec.ApprovalWait <= 0 {
258				return fmt.Errorf("%w: approval wait must be positive when approval is enabled", ErrPolicyInvalid)
259			}
260		}
261		// 最长预留时长：零表示关闭预留超时（保持既有行为）；不得为负。
262		if spec.MaxReserveDuration < 0 {
263			return fmt.Errorf("%w: max reserve duration must not be negative", ErrPolicyInvalid)
264		}
265		if !spec.StartsAt.Before(spec.EndsAt) {
266			return fmt.Errorf("%w: starts-at must be before ends-at", ErrPolicyInvalid)
267		}
268		if spec.PayerAccountID == "" || len(spec.AllowedAccountIDs) == 0 {
269			return fmt.Errorf("%w: payer account and at least one allowed account are required", ErrPolicyInvalid)
270		}
271	
272		w.mu.Lock()
273		defer w.mu.Unlock()
274	
275		if _, ok := w.policies[spec.ID]; ok {
276			return fmt.Errorf("%w: %s", ErrPolicyExists, spec.ID)
277		}
278		if _, ok := w.accounts[spec.PayerAccountID]; !ok {
279			return fmt.Errorf("%w: payer account %q: %w", ErrPolicyInvalid, spec.PayerAccountID, ErrAccountNotFound)
280		}
281		allowed := make(map[string]struct{}, len(spec.AllowedAccountIDs))
282		for _, id := range spec.AllowedAccountIDs {
283			if _, ok := w.accounts[id]; !ok {
284				return fmt.Errorf("%w: allowed account %q: %w", ErrPolicyInvalid, id, ErrAccountNotFound)
285			}
286			allowed[id] = struct{}{}
287		}
288	
289		w.policies[spec.ID] = &policy{
290			id:                 spec.ID,
291			payerAccountID:     spec.PayerAccountID,
292			allowedAccounts:    allowed,
293			operation:          spec.Operation,
294			payee:              spec.Payee,
295			startsAt:           spec.StartsAt,
296			endsAt:             spec.EndsAt,
297			maxPerRequest:      spec.MaxPerRequest,
298			maxTotal:           spec.MaxTotal,
299			approvalThreshold:  spec.ApprovalThreshold,
300			approvalWait:       spec.ApprovalWait,
301			maxReserveDuration: spec.MaxReserveDuration,
302		}
303		return nil
304	}
305	
306	// Policy 查询策略视图，含当前预留中与已结算的累计金额。查询时已到期的
307	// 预留会先被自动释放，ReservedTotal 因而反映释放后的结果。
308	func (w *Wallet) Policy(id string) (PolicyView, error) {
309		w.mu.Lock()
310		defer w.mu.Unlock()
311	
312		p, ok := w.policies[id]
313		if !ok {
314			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, id)
315		}
316		w.expireReservationsLocked(w.now())
317		return p.view(), nil
318	}
319	
320	// DeactivatePolicy 由出资账户主动停用一条代付策略，立即停止该策略继续
321	// 受理代付。停用不可撤销。
322	//
323	// 必须使用该策略出资账户绑定当前设备的有效会话：会话不存在、不属于出资
324	// 账户、设备不符、已吊销或已到期时返回 ErrNotPolicyOwner，不改变策略、
325	// 请求或账本。策略编号、会话编号、设备缺失，或理由去掉首尾空白后为空，
326	// 返回 ErrInvalidArgument。策略不存在返回 ErrPolicyNotFound。保存与比较
327	// 理由均使用去掉首尾空白后的内容。
328	//
329	// 再次停用仍须通过会话校验：理由与首次相同时幂等返回首次结果，理由不同
330	// 返回 ErrConflict；两者都不改写首次停用信息，也不增加账本记录。尚未
331	// 开始或已经结束的策略也允许停用；停用后该编号不能再保存成新策略。
332	//
333	// 停用成功时，该策略下未到等待期限的待审批请求立即转为拒绝终态，拒绝
334	// 信息说明策略被停用并包含停用理由，决定时间为停用时间；已到（含恰到）
335	// 或超过等待期限的待审批请求进入过期终态。两类处理都不冻结余额、不占用
336	// 额度，也不产生退款；其他状态的请求与其他策略不受影响。
337	func (w *Wallet) DeactivatePolicy(policyID, sessionID, deviceID, reason string) (PolicyView, error) {
338		reason = strings.TrimSpace(reason)
339		if policyID == "" || sessionID == "" || deviceID == "" || reason == "" {
340			return PolicyView{}, fmt.Errorf("%w: policy id, session id, device id and reason are required", ErrInvalidArgument)
341		}
342	
343		w.mu.Lock()
344		defer w.mu.Unlock()
345	
346		p, ok := w.policies[policyID]
347		if !ok {
348			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, policyID)
349		}
350		now := w.now()
351		if err := w.checkPolicyOwnerLocked(p, sessionID, deviceID, now); err != nil {
352			return PolicyView{}, err
353		}
354		// 鉴权通过后先释放已到期预留（停用不缩短任何未到期请求的截止时间）。
355		w.expireReservationsLocked(now)
356	
357		if p.deactivated {
358			// 停用不可撤销：理由相同返回首次结果，理由不同返回冲突，
359			// 均不改写首次信息、不增加账本记录。
360			if p.deactivateReason == reason {
361				return p.view(), nil
362			}
363			return PolicyView{}, fmt.Errorf("%w: policy %s was already deactivated with a different reason", ErrConflict, policyID)
364		}
365	
366		p.deactivated = true
367		p.deactivatedAt = now
368		p.deactivatorAccountID = p.payerAccountID
369		p.deactivateReason = reason
370	
371		w.ledger = append(w.ledger, LedgerEntry{
372			Kind:      LedgerPolicyDeactivation,
373			AccountID: p.payerAccountID,
374			PolicyID:  p.id,
375			Reason:    reason,
376			At:        now,
377		})
378	
379		// 停用瞬间结清该策略全部待审批请求：未到等待期限的随停用立即拒绝，
380		// 已到或超过期限的进入过期终态（不能因未被查询过而变成停用拒绝）。
381		for _, req := range w.requests {
382			if req.policyID != p.id || req.state != RequestPendingApproval {
383				continue
384			}
385			if now.Before(req.waitDeadline) {
386				msg := fmt.Sprintf("policy %s deactivated by payer: %s", p.id, reason)
387				req.state = RequestRejected
388				req.rejectReason = msg
389				req.decidedAt = now
390				req.approverAccountID = p.payerAccountID
391				w.ledger = append(w.ledger, LedgerEntry{
392					Kind:      LedgerRejection,
393					AccountID: req.accountID,
394					RequestID: req.requestID,
395					Reason:    msg,
396					At:        now,
397				})
398				continue
399			}
400			req.state = RequestExpired
401			req.decidedAt = now
402			w.ledger = append(w.ledger, LedgerEntry{
403				Kind:      LedgerExpiration,
404				AccountID: req.accountID,
405				RequestID: req.requestID,
406				Reason:    "approval period expired",
407				At:        now,
408			})
409		}
410		return p.view(), nil
411	}
412	
413	// checkPolicyOwnerLocked 在持锁状态下校验停用会话：必须存在、归属策略的
414	// 出资账户、绑定当前设备、未吊销且未到期。任一不满足都返回
415	// ErrNotPolicyOwner，且不改变策略、请求或账本。
416	func (w *Wallet) checkPolicyOwnerLocked(p *policy, sessionID, deviceID string, now time.Time) error {
417		sess, ok := w.sessions[sessionID]
418		if !ok {
419			return fmt.Errorf("%w: session %s", ErrNotPolicyOwner, sessionID)
420		}
421		if sess.accountID != p.payerAccountID {
422			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotPolicyOwner, sess.id, sess.accountID, p.payerAccountID)
423		}
424		if sess.deviceID != deviceID {
425			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotPolicyOwner, sess.id, sess.deviceID, deviceID)
426		}
427		if sess.revoked {
428			return fmt.Errorf("%w: session %s revoked", ErrNotPolicyOwner, sess.id)
429		}
430		if !now.Before(sess.expiresAt) {
431			return fmt.Errorf("%w: session %s expired at %s", ErrNotPolicyOwner, sess.id, sess.expiresAt.Format(time.RFC3339))
432		}
433		return nil
434	}
435	
436	// Apply 提交一笔代付申请。
437	//
438	// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
439	// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
440	// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
441	//
442	// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
443	// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
444	func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
445		if in.EstimatedFee <= 0 {
446			return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
447		}
448		if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
449			return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
450		}
451	
452		w.mu.Lock()
453		defer w.mu.Unlock()
454	
455		now := w.now()
456	
457		acc, ok := w.accounts[in.AccountID]
458		if !ok {
459			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
460		}
461		_ = acc
462	
463		sess, ok := w.sessions[in.SessionID]
464		if !ok {
465			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID))
466		}
467		if sess.accountID != in.AccountID {
468			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID))
469		}
470		if sess.deviceID != in.DeviceID {
471			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID))
472		}
473		if sess.revoked {
474			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id))
475		}
476		// 到期时刻及之后一律视为过期：[零值, ExpiresAt) 才有效。
477		if !now.Before(sess.expiresAt) {
478			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339)))
479		}
480	
481		key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
482		if existing, ok := w.requests[key]; ok {
483			// 待审批到期即过期、已预留到期即自动退回，重复申请看到的应是最新终态。
484			w.refreshPendingLocked(existing, now)
485			w.refreshReservedLocked(existing, now)
486			if existing.policyID == in.PolicyID &&
487				existing.operation == in.Operation &&
488				existing.payee == in.Payee &&
489				existing.estimatedFee == in.EstimatedFee {
490				// 幂等命中：直接返回已有结果，不再预留、不记账。
491				return existing.view(), nil
492			}
493			return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
494		}
495	
496		p, ok := w.policies[in.PolicyID]
497		if !ok {
498			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
499		}
500		// 停用后的策略不再受理新申请；历史请求的幂等查询在上方已先行处理。
501		if p.deactivated {
502			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: policy %s deactivated: %s", ErrPolicyDeactivated, p.id, p.deactivateReason))
503		}
504		if _, ok := p.allowedAccounts[in.AccountID]; !ok {
505			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
506		}
507		if in.Operation != p.operation {
508			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
509		}
510		if in.Payee != p.payee {
511			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
512		}
513		// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
514		if now.Before(p.startsAt) || !now.Before(p.endsAt) {
515			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
516				now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
517		}
518		if in.EstimatedFee > p.maxPerRequest {
519			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
520		}
521		// 资金与额度检查前释放所有已到期预留（含同一出资账户在其他策略下的
522		// 预留），因此先查余额还是先申请看到的可用金额都一致。
523		w.expireReservationsLocked(now)
524		// 预留中的费用同样占用共享累计额度。
525		if p.reservedTotal+p.spentTotal+in.EstimatedFee > p.maxTotal {
526			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
527				ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, p.reservedTotal+p.spentTotal))
528		}
529	
530		payer, ok := w.accounts[p.payerAccountID]
531		if !ok {
532			// 保存策略时已校验，这里仅作防御。
533			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
534		}
535		if payer.available < in.EstimatedFee {
536			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
537		}
538	
539		// 所有硬性检查通过：预估费用严格超过审批门槛的进入待审批，其余直接预留。
540		if p.approvalThreshold > 0 && in.EstimatedFee > p.approvalThreshold {
541			// 待审批不冻结余额、不占用共享累计额度。期限取提交时刻 + 等待时长、
542			// 策略结束时间、申请会话到期时间三者中的最早值。
543			deadline := now.Add(p.approvalWait)
544			if p.endsAt.Before(deadline) {
545				deadline = p.endsAt
546			}
547			if sess.expiresAt.Before(deadline) {
548				deadline = sess.expiresAt
549			}
550			req := &request{
551				policyID:       p.id,
552				requestID:      in.RequestID,
553				accountID:      in.AccountID,
554				payerAccountID: payer.id,
555				sessionID:      sess.id,
556				operation:      in.Operation,
557				payee:          in.Payee,
558				estimatedFee:   in.EstimatedFee,
559				state:          RequestPendingApproval,
560				createdAt:      now,
561				waitDeadline:   deadline,
562			}
563			w.requests[key] = req
564			w.ledger = append(w.ledger, LedgerEntry{
565				Kind:      LedgerPendingApproval,
566				AccountID: in.AccountID,
567				RequestID: in.RequestID,
568				Reason:    "pending approval for large amount",
569				At:        now,
570			})
571			return req.view(), nil
572		}
573	
574		// 受理：从出资账户可用余额中预留预估费用。
575		payer.available -= in.EstimatedFee
576		payer.reserved += in.EstimatedFee
577		p.reservedTotal += in.EstimatedFee
578	
579		req := &request{
580			policyID:       p.id,
581			requestID:      in.RequestID,
582			accountID:      in.AccountID,
583			payerAccountID: payer.id,
584			sessionID:      sess.id,
585			operation:      in.Operation,
586			payee:          in.Payee,
587			estimatedFee:   in.EstimatedFee,
588			state:          RequestReserved,
589			createdAt:      now,
590		}
591		// 直接受理：从受理时刻起算最长预留时长。
592		withReserveTimingLocked(req, p, now)
593		w.requests[key] = req
594		w.ledger = append(w.ledger, LedgerEntry{
595			Kind:      LedgerReserve,
596			AccountID: payer.id,
597			RequestID: in.RequestID,
598			Amount:    in.EstimatedFee,
599			Reason:    "reserve estimated fee",
600			At:        now,
601		})
602		return req.view(), nil
603	}
604	
605	// Settle 结算一笔已预留的代付请求。
606	//
607	// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
608	// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
609	// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
610	func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
611		if actualFee < 0 {
612			return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
613		}
614		w.mu.Lock()
615		defer w.mu.Unlock()
616	
617		req, p, err := w.lookupRequest(accountID, requestID)
618		if err != nil {
619			return RequestView{}, err
620		}
621		now := w.now()
622		w.refreshPendingLocked(req, now)
623		// 已到最长预留时长的预留先自动退回：此后任何结算都不能再扣款。
624		w.refreshReservedLocked(req, now)
625		switch req.state {
626		case RequestSettled:
627			if req.actualFee == actualFee {
628				return req.view(), nil
629			}
630			return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
631		case RequestCancelled:
632			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
633		case RequestReservationExpired:
634			// 预留已超时全额退回：传入非负实际费用也返回明确的超时错误，不能扣款。
635			return RequestView{}, fmt.Errorf("%w: request %s reservation expired at %s", ErrReservationExpired, requestID, req.reserveExpiredAt.Format(time.RFC3339))
636		case RequestPendingApproval, RequestRejected, RequestExpired:
637			// 结算只允许处理已预留请求。
638			return RequestView{}, fmt.Errorf("%w: request %s is %v, only reserved requests can be settled", ErrRequestNotReserved, requestID, req.state)
639		}
640	
641		if actualFee > req.estimatedFee {
642			// 拒绝并保留预留。
643			return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
644		}
645	
646		payer := w.accounts[req.payerAccountID]
647		refund := req.estimatedFee - actualFee
648	
649		// 扣除实际费用、退回差额、释放共享额度。
650		payer.reserved -= req.estimatedFee
651		payer.available += refund
652		p.reservedTotal -= req.estimatedFee
653		p.spentTotal += actualFee
654	
655		req.state = RequestSettled
656		req.actualFee = actualFee
657		req.settledAt = now
658	
659		w.ledger = append(w.ledger, LedgerEntry{
660			Kind:      LedgerSettle,
661			AccountID: payer.id,
662			RequestID: requestID,
663			Amount:    actualFee,
664			Reason:    "settle actual fee",
665			At:        now,
666		})
667		if refund > 0 {
668			w.ledger = append(w.ledger, LedgerEntry{
669				Kind:      LedgerRefund,
670				AccountID: payer.id,
671				RequestID: requestID,
672				Amount:    refund,
673				Reason:    "refund estimated-minus-actual fee",
674				At:        now,
675			})
676		}
677		return req.view(), nil
678	}
679	
680	// Cancel 取消一笔尚未结算的代付请求。
681	//
682	// 待审批请求取消后直接进入取消终态，不产生退款（本就没有冻结余额）；
683	// 已预留请求取消后全部预留退回。已结算的请求不能取消；重复取消幂等
684	// 返回，不重复记账。已拒绝或已过期的请求不能取消。
685	func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
686		w.mu.Lock()
687		defer w.mu.Unlock()
688	
689		req, p, err := w.lookupRequest(accountID, requestID)
690		if err != nil {
691			return RequestView{}, err
692		}
693		now := w.now()
694		w.refreshPendingLocked(req, now)
695		// 已到最长预留时长的预留先自动退回。
696		w.refreshReservedLocked(req, now)
697		switch req.state {
698		case RequestCancelled:
699			return req.view(), nil
700		case RequestSettled:
701			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
702		case RequestReservationExpired:
703			// 预留已超时自动全额退回：取消幂等返回已有超时结果，不重复退回、不留痕。
704			return req.view(), nil
705		case RequestPendingApproval:
706			// 待审批取消：无资金冻结，直接留取消终态。
707			req.state = RequestCancelled
708			req.decidedAt = now
709			w.ledger = append(w.ledger, LedgerEntry{
710				Kind:      LedgerCancellation,
711				AccountID: req.accountID,
712				RequestID: req.requestID,
713				Reason:    "cancel pending-approval request",
714				At:        now,
715			})
716			return req.view(), nil
717		case RequestRejected, RequestExpired:
718			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot cancel", ErrRequestNotReserved, requestID, req.state)
719		}
720	
721		// 已预留：退回全部预留。
722		payer := w.accounts[req.payerAccountID]
723	
724		payer.reserved -= req.estimatedFee
725		payer.available += req.estimatedFee
726		p.reservedTotal -= req.estimatedFee
727	
728		req.state = RequestCancelled
729	
730		w.ledger = append(w.ledger, LedgerEntry{
731			Kind:      LedgerRefund,
732			AccountID: payer.id,
733			RequestID: requestID,
734			Amount:    req.estimatedFee,
735			Reason:    "refund reserved fee on cancel",
736			At:        now,
737		})
738		return req.view(), nil
739	}
740	
741	// Approve 批准一笔待审批的大额代付请求。
742	//
743	// 审批必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
744	// 会话返回 ErrNotApprover 无权审批，且不改变请求。批准时再次检查出资
745	// 余额与共享剩余额度，足够才一次性预留全部预估费用并转为已预留；不足
746	// 时返回具体原因，保留待审批状态，期限内可再次批准。
747	//
748	// 已批准并处于预留或结算状态的请求重复批准只返回当前结果，不重复预留；
749	// 已拒绝、过期或取消的请求不能批准。截止时刻及之后不能批准。
750	func (w *Wallet) Approve(accountID, requestID, sessionID, deviceID string) (RequestView, error) {
751		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
752			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
753		}
754		w.mu.Lock()
755		defer w.mu.Unlock()
756	
757		now := w.now()
758		req, p, err := w.lookupRequest(accountID, requestID)
759		if err != nil {
760			return RequestView{}, err
761		}
762		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
763			return RequestView{}, err
764		}
765		// 鉴权通过后释放已到期预留（含同一出资账户在其他策略下的预留），使
766		// 批准的余额与额度检查计入退回；因余额或额度不足而失败的批准不会开始
767		// 预留计时。
768		w.expireReservationsLocked(now)
769		w.refreshPendingLocked(req, now)
770		if req.state == RequestExpired {
771			return RequestView{}, fmt.Errorf("%w: approval deadline %s passed", ErrApprovalExpired, req.waitDeadline.Format(time.RFC3339))
772		}
773	
774		switch req.state {
775		case RequestPendingApproval:
776			payer := w.accounts[req.payerAccountID]
777			if payer.available < req.estimatedFee {
778				return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
779			}
780			if p.reservedTotal+p.spentTotal+req.estimatedFee > p.maxTotal {
781				return RequestView{}, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
782					ErrQuotaExceeded, req.estimatedFee, p.maxTotal, p.reservedTotal+p.spentTotal)
783			}
784			// 一次性预留全部预估费用。
785			payer.available -= req.estimatedFee
786			payer.reserved += req.estimatedFee
787			p.reservedTotal += req.estimatedFee
788	
789			req.state = RequestReserved
790			req.decidedAt = now
791			req.approverAccountID = payer.id
792			// 待审批请求：等待审批的时间不计入，从批准成功时刻起算最长预留时长。
793			withReserveTimingLocked(req, p, now)
794	
795			w.ledger = append(w.ledger,
796				LedgerEntry{
797					Kind:      LedgerReserve,
798					AccountID: payer.id,
799					RequestID: req.requestID,
800					Amount:    req.estimatedFee,
801					Reason:    "reserve estimated fee on approval",
802					At:        now,
803				},
804				LedgerEntry{
805					Kind:      LedgerApproval,
806					AccountID: req.accountID,
807					RequestID: req.requestID,
808					Reason:    "approve large-amount request",
809					At:        now,
810				},
811			)
812			return req.view(), nil
813		case RequestReserved, RequestSettled:
814			// 已批准：重复批准幂等返回，不重复预留。
815			return req.view(), nil
816		default:
817			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot approve", ErrRequestNotPending, requestID, req.state)
818		}
819	}
820	
821	// Reject 拒绝一笔待审批的大额代付请求。
822	//
823	// 拒绝必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
824	// 会话返回 ErrNotApprover 无权审批，且不改变请求。拒绝理由为空或全为
825	// 空白时返回 ErrInvalidArgument 参数错误，请求保持不变。
826	//
827	// 重复拒绝且理由一致时幂等返回，不重复留痕；理由不同返回 ErrConflict。
828	// 已批准（含预留、结算）、已过期或已取消的请求不能拒绝。
829	func (w *Wallet) Reject(accountID, requestID, sessionID, deviceID, reason string) (RequestView, error) {
830		if strings.TrimSpace(reason) == "" {
831			return RequestView{}, fmt.Errorf("%w: reject reason must not be empty or blank", ErrInvalidArgument)
832		}
833		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
834			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
835		}
836		w.mu.Lock()
837		defer w.mu.Unlock()
838	
839		now := w.now()
840		req, _, err := w.lookupRequest(accountID, requestID)
841		if err != nil {
842			return RequestView{}, err
843		}
844		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
845			return RequestView{}, err
846		}
847		w.refreshPendingLocked(req, now)
848	
849		switch req.state {
850		case RequestPendingApproval:
851			req.state = RequestRejected
852			req.rejectReason = reason
853			req.decidedAt = now
854			req.approverAccountID = req.payerAccountID
855	
856			w.ledger = append(w.ledger, LedgerEntry{
857				Kind:      LedgerRejection,
858				AccountID: req.accountID,
859				RequestID: req.requestID,
860				Reason:    reason,
861				At:        now,
862			})
863			return req.view(), nil
864		case RequestRejected:
865			if req.rejectReason == reason {
866				return req.view(), nil
867			}
868			return RequestView{}, fmt.Errorf("%w: request %s already rejected with a different reason", ErrConflict, requestID)
869		default:
870			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot reject", ErrRequestNotPending, requestID, req.state)
871		}
872	}
873	
874	// checkApproverLocked 在持锁状态下校验审批会话：必须存在、归属出资账户、
875	// 绑定当前设备、未吊销且未过期。任一不满足都返回 ErrNotApprover，且不
876	// 改变请求。
877	func (w *Wallet) checkApproverLocked(req *request, sessionID, deviceID string, now time.Time) error {
878		sess, ok := w.sessions[sessionID]
879		if !ok {
880			return fmt.Errorf("%w: session %s", ErrNotApprover, sessionID)
881		}
882		if sess.accountID != req.payerAccountID {
883			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotApprover, sess.id, sess.accountID, req.payerAccountID)
884		}
885		if sess.deviceID != deviceID {
886			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotApprover, sess.id, sess.deviceID, deviceID)
887		}
888		if sess.revoked {
889			return fmt.Errorf("%w: session %s revoked", ErrNotApprover, sess.id)
890		}
891		if !now.Before(sess.expiresAt) {
892			return fmt.Errorf("%w: session %s expired at %s", ErrNotApprover, sess.id, sess.expiresAt.Format(time.RFC3339))
893		}
894		return nil
895	}
896	
897	// refreshPendingLocked 在持锁状态下检查待审批请求是否已到期限；到期
898	// （含到期时刻）则转为过期终态并记账。必须在持锁状态下调用。
899	func (w *Wallet) refreshPendingLocked(req *request, now time.Time) {
900		if req.state != RequestPendingApproval {
901			return
902		}
903		if now.Before(req.waitDeadline) {
904			return
905		}
906		req.state = RequestExpired
907		req.decidedAt = now
908		w.ledger = append(w.ledger, LedgerEntry{
909			Kind:      LedgerExpiration,
910			AccountID: req.accountID,
911			RequestID: req.requestID,
912			Reason:    "approval period expired",
913			At:        now,
914		})
915	}
916	
917	// refreshReservedLocked 在持锁状态下检查单笔已预留请求是否已到最长预留
918	// 时长；截止时刻及之后转为“预留超时”终态并退回全额预留。必须在持锁状态
919	// 下调用。
920	func (w *Wallet) refreshReservedLocked(req *request, now time.Time) {
921		if req.state != RequestReserved || req.reserveDuration <= 0 {
922			return
923		}
924		if now.Before(req.reserveDeadline) {
925			return
926		}
927		w.expireReservationLocked(req, req.reserveDeadline)
928	}
929	
930	// expirePendingApprovalsLocked 惰性结清当前全部已到等待期限（含到期时刻）
931	// 的待审批请求，使它们进入过期终态并留下状态记录。按等待截止时刻顺序
932	// 处理（同截止时刻按使用账户、请求编号排序），保证账本追加顺序确定。
933	// 必须在持锁状态下调用。
934	func (w *Wallet) expirePendingApprovalsLocked(now time.Time) {
935		due := make([]*request, 0)
936		for _, req := range w.requests {
937			if req.state == RequestPendingApproval && !now.Before(req.waitDeadline) {
938				due = append(due, req)
939			}
940		}
941		sort.SliceStable(due, func(i, j int) bool {
942			if due[i].waitDeadline.Equal(due[j].waitDeadline) {
943				if due[i].accountID != due[j].accountID {
944					return due[i].accountID < due[j].accountID
945				}
946				return due[i].requestID < due[j].requestID
947			}
948			return due[i].waitDeadline.Before(due[j].waitDeadline)
949		})
950		for _, req := range due {
951			w.refreshPendingLocked(req, now)
952		}
953	}
954	
955	// expireReservationsLocked 惰性结清当前全部已到期（含到期时刻）的预留。
956	// 所有账户/余额/策略/请求/账本查询以及新申请、批准的资金检查入口都先调用
957	// 它，因此调用者无须逐笔取消即可看到已到期预留的释放结果。释放时间一律
958	// 记录为各请求自己的截止时刻，而不是处理时刻；账本按截止时刻顺序追加。
959	// 必须在持锁状态下调用。
960	func (w *Wallet) expireReservationsLocked(now time.Time) {
961		due := make([]*request, 0)
962		for _, req := range w.requests {
963			if req.state == RequestReserved && req.reserveDuration > 0 && !now.Before(req.reserveDeadline) {
964				due = append(due, req)
965			}
966		}
967		sort.SliceStable(due, func(i, j int) bool {
968			if due[i].reserveDeadline.Equal(due[j].reserveDeadline) {
969				if due[i].accountID != due[j].accountID {
970					return due[i].accountID < due[j].accountID
971				}
972				return due[i].requestID < due[j].requestID
973			}
974			return due[i].reserveDeadline.Before(due[j].reserveDeadline)
975		})
976		for _, req := range due {
977			w.expireReservationLocked(req, req.reserveDeadline)
978		}
979	}
980	
981	// expireReservationLocked 将一笔已预留请求转为 RequestReservationExpired
982	// 终态：全额退回预估费用到出资账户可用余额，减少出资账户预留余额与该
983	// 策略的预留总额，不增加实际费用或已花费总额。账本增加一条出资账户的
984	// 全额退款记录和一条使用账户的零金额超时状态记录，均关联请求编号。
985	// 必须在持锁状态下调用。
986	func (w *Wallet) expireReservationLocked(req *request, deadline time.Time) {
987		payer := w.accounts[req.payerAccountID]
988		payer.reserved -= req.estimatedFee
989		payer.available += req.estimatedFee
990		if p := w.policies[req.policyID]; p != nil {
991			p.reservedTotal -= req.estimatedFee
992		}
993		req.state = RequestReservationExpired
994		req.reserveExpiredAt = deadline
995	
996		w.ledger = append(w.ledger,
997			LedgerEntry{
998				Kind:      LedgerRefund,
999				AccountID: payer.id,
1000				RequestID: req.requestID,
1001				Amount:    req.estimatedFee,
1002				Reason:    "refund reserved fee on reservation timeout",
1003				At:        deadline,
1004			},
1005			LedgerEntry{
1006				Kind:      LedgerReservationExpiration,
1007				AccountID: req.accountID,
1008				RequestID: req.requestID,
1009				Reason:    "reservation timed out before settlement",
1010				At:        deadline,
1011			},
1012		)
1013	}
1014	
1015	// withReserveTimingLocked 在费用完成预留时写入预留计时信息：预留时刻为
1016	// 受理/批准成功的时刻，截止时刻为预留时刻加策略最长预留时长；策略未启用
1017	// 超时（时长为零）时截止时刻保持零值。必须在持锁状态下调用。
1018	func withReserveTimingLocked(req *request, p *policy, reservedAt time.Time) {
1019		req.reservedAt = reservedAt
1020		req.reserveDuration = p.maxReserveDuration
1021		if p.maxReserveDuration > 0 {
1022			req.reserveDeadline = reservedAt.Add(p.maxReserveDuration)
1023		}
1024	}
1025	
1026	// Request 查询某使用账户下的代付请求。待审批请求到期即转为过期终态，
1027	// 已预留请求到最长预留时长即转为预留超时终态，查询结果反映最新状态；
1028	// 超时释放时间记录的是截止时刻本身，而不是本次查询时刻。
1029	func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
1030		w.mu.Lock()
1031		defer w.mu.Unlock()
1032	
1033		req, _, err := w.lookupRequest(accountID, requestID)
1034		if err != nil {
1035			return RequestView{}, err
1036		}
1037		now := w.now()
1038		w.refreshPendingLocked(req, now)
1039		w.refreshReservedLocked(req, now)
1040		return req.view(), nil
1041	}
1042	
1043	// Ledger 返回全部账本记录的副本，按产生顺序排列。
1044	// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
1045	// 查询时已到期预留的自动退款与超时留痕也会在返回前补齐。
1046	func (w *Wallet) Ledger() []LedgerEntry {
1047		w.mu.Lock()
1048		defer w.mu.Unlock()
1049	
1050		w.expireReservationsLocked(w.now())
1051		out := make([]LedgerEntry, len(w.ledger))
1052		copy(out, w.ledger)
1053		return out
1054	}
1055	
1056	// AccountLedger 返回与指定账户相关的账本记录副本。
1057	//
1058	// 对出资账户返回预留、扣减、退回等资金变动记录；对待审批、批准、拒绝、
1059	// 取消、过期等状态记录（无金额变动），其 AccountID 为发起申请的使用
1060	// 账户，因此按使用账户查询可看到该请求的完整状态留痕。
1061	func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
1062		w.mu.Lock()
1063		defer w.mu.Unlock()
1064	
1065		w.expireReservationsLocked(w.now())
1066		var out []LedgerEntry
1067		for _, e := range w.ledger {
1068			if e.AccountID == accountID {
1069				out = append(out, e)
1070			}
1071		}
1072		return out
1073	}
1074	
1075	// lookupRequest 必须在持锁状态下调用。
1076	func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
1077		req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
1078		if !ok {
1079			return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
1080		}
1081		return req, w.policies[req.policyID], nil
1082	}
1083	
1084	// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
1085	func (w *Wallet) reject(in RequestInput, cause error) error {
1086		w.mu.Lock()
1087		defer w.mu.Unlock()
1088		w.appendRejection(in, w.now(), cause)
1089		return cause
1090	}
1091	
1092	// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
1093	func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
1094		w.appendRejection(in, at, cause)
1095		return cause
1096	}
1097	
1098	// appendRejection 必须在持锁状态下调用。拒绝记录不涉及金额变动，
1099	// 只记录使用账户、请求编号与具体原因。
1100	func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
1101		w.ledger = append(w.ledger, LedgerEntry{
1102			Kind:      LedgerRejection,
1103			AccountID: in.AccountID,
1104			RequestID: in.RequestID,
1105			Reason:    cause.Error(),
1106			At:        at,
1107		})
1108	}
1109	
1110	func (a *account) view() AccountView {
1111		return AccountView{
1112			ID: a.id,
1113			Balances: Balances{
1114				Available: a.available,
1115				Reserved:  a.reserved,
1116			},
1117			CreatedAt: a.createdAt,
1118		}
1119	}
1120	
1121	func (s *session) view() SessionView {
1122		state := SessionActive
1123		if s.revoked {
1124			state = SessionRevoked
1125		}
1126		return SessionView{
1127			ID:        s.id,
1128			AccountID: s.accountID,
1129			DeviceID:  s.deviceID,
1130			ExpiresAt: s.expiresAt,
1131			State:     state,
1132			CreatedAt: s.createdAt,
1133		}
1134	}
1135	
1136	func (p *policy) view() PolicyView {
1137		ids := make([]string, 0, len(p.allowedAccounts))
1138		for id := range p.allowedAccounts {
1139			ids = append(ids, id)
1140		}
1141		return PolicyView{
1142			PolicySpec: PolicySpec{
1143				ID:                 p.id,
1144				PayerAccountID:     p.payerAccountID,
1145				AllowedAccountIDs:  ids,
1146				Operation:          p.operation,
1147				Payee:              p.payee,
1148				StartsAt:           p.startsAt,
1149				EndsAt:             p.endsAt,
1150				MaxPerRequest:      p.maxPerRequest,
1151				MaxTotal:           p.maxTotal,
1152				ApprovalThreshold:  p.approvalThreshold,
1153				ApprovalWait:       p.approvalWait,
1154				MaxReserveDuration: p.maxReserveDuration,
1155			},
1156			ReservedTotal:        p.reservedTotal,
1157			SpentTotal:           p.spentTotal,
1158			Deactivated:          p.deactivated,
1159			DeactivatedAt:        p.deactivatedAt,
1160			DeactivatorAccountID: p.deactivatorAccountID,
1161			DeactivateReason:     p.deactivateReason,
1162		}
1163	}
1164	
1165	func (r *request) view() RequestView {
1166		return RequestView{
1167			PolicyID:          r.policyID,
1168			RequestID:         r.requestID,
1169			AccountID:         r.accountID,
1170			PayerAccountID:    r.payerAccountID,
1171			Operation:         r.operation,
1172			Payee:             r.payee,
1173			EstimatedFee:      r.estimatedFee,
1174			ActualFee:         r.actualFee,
1175			State:             r.state,
1176			CreatedAt:         r.createdAt,
1177			SettledAt:         r.settledAt,
1178			WaitDeadline:      r.waitDeadline,
1179			ReservedAt:        r.reservedAt,
1180			ReserveDuration:   r.reserveDuration,
1181			ReserveDeadline:   r.reserveDeadline,
1182			ReserveExpiredAt:  r.reserveExpiredAt,
1183			DecidedAt:         r.decidedAt,
1184			ApproverAccountID: r.approverAccountID,
1185			RejectReason:      r.rejectReason,
1186		}
1187	}
