	if r.RejectReason != "" {
		t.Fatalf("timeout request must not carry reject reason: %q", r.RejectReason)
	}
	if countKind(w2.Ledger(), LedgerRejection) != 0 {
		t.Fatal("reservation timeout must not be recorded as rejection")
	}
}

